export interface ListBinding {
  path: JsonPointer;
  template: ViewComponentId;
}
/**
 * A prop whose value is read from the view's data. A path that does not resolve renders as
 * empty.
 */
export interface Binding {
  path: JsonPointer;
}
/**
 * Its children side by side, sharing the width, and wrapping onto the next line when they
 * run out of room.
 */
export interface ViewRow {
  children?: ViewComponentId[] | ListBinding;
  component: "Row";
  id: ViewComponentId;
}
/**
 * A paragraph of text.
 */
export interface ViewText {
  component: "Text";
  id: ViewComponentId;
  text: TextProp;
}
/**
 * A link that opens its target, an http, https or mailto address, in a new tab.
 */
export interface ViewLink {
  component: "Link";
  href: TextProp;
  id: ViewComponentId;
  label: TextProp;
}
/**
 * A table with one row per item of an array in the view's data.
 */
export interface ViewTable {
  columns: ViewTableColumn[];
  component: "Table";
  id: ViewComponentId;
  rows: Binding;
}
/**
 * A table column: its header, and the component each row shows in it, with the component's
 * paths read in the row.
 */
export interface ViewTableColumn {
  cell: ViewComponentId;
  header: TextProp;
}
/**
 * A short label, such as a stage.
 */
export interface ViewBadge {
  component: "Badge";
  id: ViewComponentId;
  label: TextProp;
}
/**
 * A board with one column per item of an array in the view's data. Each column's title and
 * cards are read in its item.
 */
export interface ViewKanban {
  cards: ListBinding;
  columns: Binding;
  component: "Kanban";
  id: ViewComponentId;
  title: TextProp;
}
/**
 * One figure with its label, and an optional line under it.
 */
export interface ViewStat {
  component: "Stat";
  description?: TextProp | null;
  id: ViewComponentId;
  label: TextProp;
  value: TextProp;
}
/**
 * A line, bar or area chart of the points in an array in the view's data. Each point's place
 * on the x axis and its series' values are read in the point.
 */
export interface ViewChart {
  component: "Chart";
  id: ViewComponentId;
  kind: ChartKind;
  points: Binding;
  /**
   * @minItems 1
   */
  series: [ViewChartSeries, ...ViewChartSeries[]];
  x: Binding;
}
export interface ViewChartSeries {
  label: string;
  value: Binding;
}
/**
 * A read-only checklist with one entry per item of an array in the view's data. Each entry's
 * label and whether it is done are read in its item.
 */
export interface ViewChecklist {
  component: "Checklist";
  done: boolean | Binding;
  id: ViewComponentId;
  items: Binding;
  label: TextProp;
}
export interface ViewListCommand {}
export interface ResultFrame {
  id: string;
  result: {
    [k: string]: JsonValue;
  };
  type: "result";
}
/**
 * A frame the server could not read carries no id.
 */
export interface ErrorFrame {
  error: ErrorEnvelope;
  id?: string | null;
  type: "error";
}
export interface ErrorEnvelope {
  code: ErrorCode;
  fields?: {
    [k: string]: string;
  };
  message: string;
  retryable: boolean;
}
export interface SubscribedFrame {
  head_sequence: number;
  id: string;
  type: "subscribed";
}
export interface ItemFrame {
  id: string;
  item: {
    [k: string]: JsonValue;
  };
  type: "item";
}
export interface EndFrame {
  id: string;
  type: "end";
}
/**
 * Open a browser at *url* with no turn, for the user to sign in and save as a profile, and
 * watch it frame by frame. The browser closes when the watching stops.
 */
export interface BrowserTakeoverStartCommand {
  takeover_id: string;
  url: string;
}
/**
 * Follow every factory run of the hub as its state changes. Nothing is replayed.
 */
export interface FactoryRunSubscribeCommand {}
export interface ThreadSubscribeCommand {
  after_sequence?: number;
  thread_id: string;
}
export interface Event {
  payload:
    | ModePinned
    | TurnStarted
    | MessageDelta
    | ModelCompleted
    | ToolCall
    | ToolGated
    | ToolResult
    | Warning
    | ApprovalRequested
    | TakeoverRequested
    | TurnCompleted
    | TurnFailed
    | TurnInterrupted
    | TurnRated
    | RunDelegated
    | RunStopped
    | MemoryRecapped
    | MemoryRecalled
    | MemoryConsolidated
    | ProfileCounted
    | RoutineFailureHandled
    | RoutineFailuresReset
    | SignalReceived
    | WorkspaceReverted
    | NotificationRaised
    | NotificationAccepted
    | NotificationRefused
    | ViewChanged;
  sequence: number;
  thread_id: string;
  timestamp: string;
  turn_id: string;
}
export interface ModePinned {
  mode: PermissionMode;
  type: "mode.pinned";
}
export interface TurnStarted {
  message: string;
  model: string;
  origin?: UserOrigin | RoutineOrigin | FactoryRunOrigin | HomeInstanceOrigin;
  permission_mode?: PermissionMode | null;
  profile_version?: string | null;
  prompt_version?: string | null;
  snapshot?: string | null;
  type: "turn.started";
}
export interface MessageDelta {
  text: string;
  type: "message.delta";
}
export interface ModelCompleted {
  cache_creation_tokens?: number;
  cache_read_tokens?: number;
  duration_ms: number;
  input_tokens: number;
  model: string;
  output_tokens: number;
  type: "model.completed";
}
export interface ToolCall {
  arguments: {
    [k: string]: JsonValue;
  };
  call_id: string;
  name: string;
  type: "tool.call";
  write?: boolean | null;
}
export interface ToolGated {
  action: GateOutcome;
  call_id: string;
  decided_by: GateDecider;
  name: string;
  reason?: string | null;
  rule: string;
  type: "tool.gated";
}
export interface ToolResult {
  call_id: string;
  duration_ms?: number | null;
  error: boolean;
  name: string;
  output: string;
  type: "tool.result";
}
/**
 * The turn waits while the user drives its browser, until the user finishes (ADR 0113).
 */
export interface TakeoverRequested {
  reason: string;
  takeover_id: string;
  type: "takeover.requested";
}
export interface TurnCompleted {
  cache_creation_tokens?: number;
  cache_read_tokens?: number;
  input_tokens: number;
  outcome?: CompletionOutcome;
  output_tokens: number;
  snapshot?: string | null;
  type: "turn.completed";
}
export interface TurnFailed {
  cache_creation_tokens?: number;
  cache_read_tokens?: number;
  code: ErrorCode;
  input_tokens?: number;
  message: string;
  output_tokens?: number;
  snapshot?: string | null;
  type: "turn.failed";
}
export interface TurnInterrupted {
  cache_creation_tokens?: number;
  cache_read_tokens?: number;
  input_tokens?: number;
  output_tokens?: number;
  snapshot?: string | null;
  type: "turn.interrupted";
}
/**
 * A delegated run. A client step's names its step and attempt; a tool's names neither.
 */
export interface RunDelegated {
  attempt?: number | null;
  run: DelegatedRun;
  step?: StepId | null;
  type: "run.delegated";
}
/**
 * A factory run this instance handed in stopped, as the hub told it.
 */
export interface RunStopped {
  stop: RunStop;
  type: "run.stopped";
}
export interface MemoryRecapped {
  cache_creation_tokens?: number;
  cache_read_tokens?: number;
  input_tokens: number;
  model?: string | null;
  node: string | null;
  output_tokens: number;
  type: "memory.recapped";
}
/**
 * A memory search or open returned these facts and episodes to the turn.
 *
 * A ``kinby memory search`` in a factory run's coding session is recorded on the run's thread
 * instead, naming the step, the attempt and the session.
 */
export interface MemoryRecalled {
  attempt?: number | null;
  nodes: string[];
  session?: string | null;
  step?: StepId | null;
  type: "memory.recalled";
}
/**
 * A consolidation finished its writes. Every episode it lists is covered.
 */
export interface MemoryConsolidated {
  episodes: string[];
  facts: string[];
  type: "memory.consolidated";
}
/**
 * The provider's tokenizer counted a profile version, once for every turn that ran with it.
 */
export interface ProfileCounted {
  tokens: number;
  type: "profile.counted";
  version: string;
}
export interface RoutineFailureHandled {
  name: string;
  notice?: RoutineNotice | null;
  type: "routine.failure.handled";
}
export interface RoutineFailuresReset {
  name: string;
  type: "routine.failures.reset";
}
export interface SignalReceived {
  delivery: Delivery;
  origin: RoutineOrigin;
  type: "signal.received";
}
export interface Delivery {
  body: string;
  content_type: string;
  delivery_id?: string | null;
  headers: {
    [k: string]: string;
  };
  received_at: string;
}
/**
 * The workspace went from ``previous`` back to ``restored``, the target's before tree.
 */
export interface WorkspaceReverted {
  previous: string;
  restored: string;
  target_turn_id: string;
  type: "workspace.reverted";
}
/**
 * A notification the instance raises on its hub route, again on each scheduler pass, until
 * the hub answers it.
 */
export interface NotificationRaised {
  approval?: WaitingApproval | null;
  /**
   * @maxItems 4
   */
  options?: [] | [string] | [string, string] | [string, string, string] | [string, string, string, string];
  source: string;
  text: string;
  title: string;
  type: "notification.raised";
}
/**
 * The hub took the notification, and sends it through its channels.
 */
export interface NotificationAccepted {
  notification_id: string;
  raised: number;
  type: "notification.accepted";
}
/**
 * The hub refused the notification, so it is never sent.
 */
export interface NotificationRefused {
  raised: number;
  reason: string;
  type: "notification.refused";
}
/**
 * A turn wrote or deleted a view. The view's content stays in the view.
 */
export interface ViewChanged {
  change: ViewChange;
  title: string;
  type: "view.changed";
  view: ViewId;
}
/**
 * Watch the browser of the takeover the thread's turn is parked on, frame by frame.
 */
export interface ThreadTakeoverStartCommand {
  takeover_id: string;
  thread_id: string;
}
/**
 * Follow one view: the view as it is, then the whole view again after each write, until it
 * is deleted.
 */
export interface ViewSubscribeCommand {
  id: ViewId;
}
